// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        address ownerBefore = c.owner();
        // Attempt to call addReward; catch any revert
        try c.addReward(rewardToken) {
            // No revert: assert owner unchanged
            assertTrue(c.owner() == ownerBefore, "Owner changed after addReward");
        } catch {
            // If it reverts, the bug is present (mutant reverts on transferOwnership, but addReward should not revert)
            // Assert that the revert is only due to the bug and owner is unchanged
            assertTrue(c.owner() == ownerBefore, "Owner changed even on revert");
        }
    }
}

