pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Restrict to zero address only to check the rule that transferOwnership(0) reverts
        vm.assume(newOwner == address(0));

        // Call addReward with a dummy token address (any non-zero address works)
        // This is the entry point mentioned in the difference description
        c.addReward(address(0xdead));

        // Attempt to transfer ownership to zero address, should revert in reference
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(0)));

        // The reference contract should revert; the buggy one may not
        assertTrue(success != true);
    }
}

