pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0) && rewardToken != address(this));

        address owner = c.owner();

        // Ensure reward token is not already added
        vm.assume(c.rewardPeriodFinish(rewardToken) == 0);

        // Prank as owner to call addReward
        vm.prank(owner);
        c.addReward(rewardToken);

        // Attempt to transfer ownership to address(0)
        bool reverted;
        try c.transferOwnership(address(0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}

