pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address rewardToken, uint256 amount, uint256 depositETH) public {
        vm.assume(rewardToken != address(0));
        vm.assume(amount > 0 && amount <= type(uint216).max);
        vm.assume(depositETH <= 100 ether);

        // Add reward token
        c.addReward(rewardToken);

        // Get totalSupply before any stake
        uint256 supplyBefore = c.totalSupply();

        // Send ETH to the contract (this changes address(this).balance but not stakes)
        vm.deal(address(c), depositETH);

        // Get totalSupply after ETH deposit
        uint256 supplyAfter = c.totalSupply();

        // The rule: totalSupply must not change when ETH is sent to the contract
        assertTrue(supplyBefore == supplyAfter, "totalSupply changed after ETH deposit");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property() public {
        // After calling addReward (with any token address), totalSupply() must equal _totalSupply
        // We cannot read _totalSupply directly, but we can infer it: the only way to change it is via stake/withdraw.
        // However, the bug replaces totalSupply() with stakingToken.balanceOf(address(this)).
        // So we check that totalSupply() is independent of stakingToken balance.
        // Transfer some tokens to the contract to alter stakingToken.balanceOf but not _totalSupply.
        address token = address(0x1234567890123456789012345678901234567890);
        vm.assume(token != address(this));
        // Ensure token has enough balance to transfer
        vm.deal(token, 100 ether);
        vm.prank(token);
        (bool sent, ) = address(c).call{value: 0}(""); // just to make token address appear
        // We'll just use the fact that the stakingToken is set in constructor to address(this).
        // Send some ether to the contract (stakingToken is an ERC20, but address(this) has no fallback, but we can send ETH)
        // Actually stakingToken is address(this) (the test contract). Let's send ETH to the test contract itself to change its balance.
        // But the stakingToken.balanceOf(address(c)) is ERC20 balance, not ETH. So we need ERC20 tokens.
        // Deploy a simple ERC20 token to act as stakingToken? No, we must use address(this) as per setup.
        // The stakingToken is address(this) (test contract). So we can mint tokens to the test contract.
        // Actually we can just call c.addReward(token) and then check that totalSupply() returns something not affected by our token transfers.
        // The bug returns stakingToken.balanceOf(address(this)) which is ERC20 balance of address(this) (the test contract).
        // We can control that by transferring ERC20 tokens to the test contract.
        // But we don't have an ERC20 at hand. So let's use a different approach: after addReward, totalSupply() should be 0 because no stakes.
        // In reference, after addReward, totalSupply() returns 0 (since _totalSupply is 0).
        // In mutant, if stakingToken.balanceOf(address(this)) > 0, totalSupply() returns >0.
        // We can make stakingToken.balanceOf(address(this)) >0 by sending ETH to the test contract? No, ERC20 balance.
        // We can deploy a minimal ERC20 to use as stakingToken, but the setup is fixed.
        // So we need another invariant: after addReward, totalSupply() should equal the value before addReward.
        // Call addReward and check totalSupply() stays the same.
        uint256 before = c.totalSupply();
        c.addReward(token);
        uint256 after = c.totalSupply();
        assertTrue(before == after);
    }
}

