pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker) public {
        vm.assume(staker != address(0) && staker != address(this));
        // Add a reward token so that rewardTokens.length > 0 (required for later state changes)
        address rewardToken = address(0x1);
        c.addReward(rewardToken);
        // Stake some tokens so that totalSupply > 0 and some balance is assigned
        uint256 stakeAmount = 100;
        vm.deal(staker, stakeAmount);
        vm.startPrank(staker);
        // We need stakingToken balance; for simplicity, use the contract's own tokens? 
        // Actually, we can just stake directly: but stakingToken is address(this) from constructor.
        // So we transfer stakingToken to staker first.
