        c.addReward(token1);
        uint256 lastUpdate1After = c.rewardData(token1).lastUpdateTime;
        // If token1 was not added before, lastUpdateTime must be set to current time
        if (lastUpdate1Before == 0) {
            assertTrue(lastUpdate1After >= block.timestamp - 1 && lastUpdate1After <= block.timestamp);
