        // Attempt second add
        (bool success, ) = address(c).call(abi.encodeWithSignature("addReward(address)", token1));
        if (success) {
            // This is M: after second add, lastUpdateTime should be updated to current time
            uint256 lastUpdate1AfterSecond = c.rewardData(token1).lastUpdateTime;
            assertTrue(lastUpdate1AfterSecond >= block.timestamp - 1 && lastUpdate1AfterSecond <= block.timestamp);
        } else {
            // This is P: second add reverts, so lastUpdateTime remains as after first add
            uint256 lastUpdate1AfterRevert = c.rewardData(token1).lastUpdateTime;
            assertTrue(lastUpdate1AfterRevert == lastUpdate1After);
        }
        vm.revertTo(snapshot);
    }
