import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        c.addReward(address(0x1));
        // We can't directly call migrateStake because it requires migrator and a valid oldStaking.
        // Instead, we check that after adding a reward, staking a non-zero amount works correctly.
        // The property: staking should increase total supply by the amount.
        uint256 supplyBefore = c.totalSupply();
        // Mint tokens to this contract to stake
        // Deploy a simple ERC20 for testing
        // Actually, we can just test the addReward part and observe that balanceOf for staker changes correctly via stake.
        // But the bug is in migrateStake, which is only callable by migrator. We can set migrator.
        vm.prank(address(this));
        c.setMigrator(address(this));
        // We need a valid oldStaking contract. We'll deploy a minimal one that returns.
        // Since we cannot deploy another contract, we use a cheat: we just call migrateStake with a dummy address.
        // But that will revert because the oldStaking.migrateWithdraw will fail.
        // Instead, the property we can test is: after addReward, the reward data is correctly initialized.
        // Actually, the given difference says: after addReward, P.migrateStake() != M.migrateStake().
        // migrateStake is a function, not a getter. So we need to observe the effect of calling migrateStake.
        // The only observable effect via public surface is totalSupply and balanceOf after calling migrateStake.
        // But we need a working oldStaking contract. Let's use a different approach: we can use vm.etch to put code.
        // However, the test must be self-contained and not deploy extra contracts.
        // The simplest general rule: after addReward, calling migrateStake should increase totalSupply by amount, not 0.
        // We'll deploy a minimal contract at oldStaking that does nothing but return.
        // That's too complex. Instead, we observe that the bug changes the staked amount.
        // We can test by directly staking via stake() and then checking that totalSupply increases by amount.
        // That property holds for both P and M, so not a differentiating rule.
        // The differentiating rule: When migrateStake is called with amount X, totalSupply increases by X (not 0).
        // We can test this by using a mock oldStaking contract that we deploy here.
        // But HARD RULES: no other contracts. So we must use only C's public surface.
        // We can use vm.mockCall to simulate the oldStaking call.
        // Let's do that:
        address oldStaking = address(0x1234);
        bytes memory mockReturnData = abi.encode();
        vm.mockCall(oldStaking, abi.encodeWithSignature("migrateWithdraw(address,uint256)", address(this), amount), mockReturnData);
        uint256 supplyBeforeMigrate = c.totalSupply();
        c.migrateStake(oldStaking, amount);
        uint256 supplyAfterMigrate = c.totalSupply();
        assertTrue(supplyAfterMigrate == supplyBeforeMigrate + amount, "totalSupply should increase by amount after migrateStake");
    }
}

